import { IHikingRulesDTO } from '../@types/hiking.backendTypes';
import { HikingAccessGroup } from '../@types/hiking.rules';

export const getHikingAccessGroupRulesDTO = async (
  rulesDTO: IHikingRulesDTO,
): Promise<HikingAccessGroup> => {
  if (rulesDTO.boss) {
    return HikingAccessGroup.Boss;
  }

  if (rulesDTO.full) {
    return HikingAccessGroup.Full;
  }
  if (rulesDTO.all) {
    return HikingAccessGroup.All;
  }
  if (rulesDTO.routes) {
    return HikingAccessGroup.Routes;
  }
  if (rulesDTO.kitchen) {
    return HikingAccessGroup.Kitchen;
  }
  if (rulesDTO.health) {
    return HikingAccessGroup.Health;
  }
  if (rulesDTO.media) {
    return HikingAccessGroup.Media;
  }
  if (rulesDTO.time) {
    return HikingAccessGroup.Time;
  }
  if (rulesDTO.equip) {
    return HikingAccessGroup.Equip;
  }
  if (rulesDTO.money) {
    return HikingAccessGroup.Money;
  }
  if (rulesDTO.info) {
    return HikingAccessGroup.Info;
  }
  if (rulesDTO.workouts) {
    return HikingAccessGroup.Workouts;
  }
  if (rulesDTO.member) {
    return HikingAccessGroup.Member;
  }

  return HikingAccessGroup.Readonly;
};
