import { get } from '@helpers/httpClient';

import { getHikingAccessGroupRulesDTO } from '../@mappers/hikingRules.mapper';
import { IHikingRulesDTO } from '../@types/hiking.backendTypes';
import { HikingAccessGroup } from '../@types/hiking.rules';

export const getHikingAccessGroupAsync = async (id_hiking: number): Promise<HikingAccessGroup> => {
  const res = await get<IHikingRulesDTO, { id_hiking: number }>('/ajax/hiking/rules.php', {
    id_hiking,
  });
  return getHikingAccessGroupRulesDTO(res);
};
